    static let scoring = valueCases.map(\.question)

    struct PlanningCase: Sendable {
        let id: String
        let trump: Suit?
        let hands: [[PlayingCard]]
        let priorEyes: Int
        let guaranteedEyes: [Int]
        let reasoning: String

        var question: QuizQuestion {
            let game = trump.map { "\($0.displayName)spiel" } ?? "Grand"
            let labels = hands.map { $0.map(\.spokenName).joined(separator: ", ") }
            let prompt = "\(game), noch drei Stiche. Du bist Alleinspieler und spielst aus. \(priorEyes) Augen einschließlich Skat, Reizwert gedeckt. Alle Restkarten sind bekannt:\n\nDu: \(labels[0]).\nLinks: \(labels[1]).\nRechts: \(labels[2]).\n\nWelches Ausspiel erzwingt gegen jede legale Abwehr mindestens 61 Augen?"
            let answerIndex = guaranteedEyes.firstIndex(of: guaranteedEyes.max()!)!
            return QuizQuestion(id: id, prompt: prompt, tiles: hands[0],
                                choices: hands[0].map(\.spokenName), answerIndex: answerIndex,
                                explanation: reasoning)
        }
    }

    static let planningCases: [PlanningCase] = [
        PlanningCase(id: "vertieft-plan-01", trump: .spades,
